#include "informationRegister.h"

/* PNG */
static const wxString s_informationRegister_16_png = wxT("");

wxIcon ibValueMetaObjectInformationRegister::GetIcon() const
{
	return GetIconGroup();
}

wxIcon ibValueMetaObjectInformationRegister::GetIconGroup()
{
	static wxIcon icon =
		ibBackendPicture::GetIconFromBase64(s_informationRegister_16_png, wxSize(16, 16));

	return icon;
}
